#ifndef SUM_ARRAY_H
#define SUM_ARRAY_H

/* 返回 arr 中前 count 个元素的和。
 * 合同：arr 指向至少 count 个 int，count 是元素个数。 */
int sum_array(int *arr, int count);

#endif

#include "sum_array.h"

int sum_array(int *arr, int count) {
    int total = 0;

    for (int i = 0; i < count; i++) {
        total += arr[i];
    }

    return total;
}

#include <stdio.h>
#include "sum_array.h"

int main(void) {
    int values[] = {3, 1, 4, 1, 5};

    int count = sizeof(values) / sizeof(values[0]);

    int total = sum_array(values, count);

    printf("count=%d total=%d\n", count, total);

    return 0;
}
